insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_econadv_v1'
from (values
('113.61.c.1.A',3,'Dana tracks stock prices for fun and likes comparing company reports. Which economics career area connects best to this interest?','["Financial analysis", "Landscape design", "Plumbing", "Commercial fishing"]'::jsonb,0,'Linking interests to a career is the start of an advanced economics project.','original'),
('113.61.c.1.A',3,'Eli enjoys studying how prices change when a store runs out of an item. Which discipline matches his interest?','["Metallurgy", "Microeconomics", "Astronomy", "Anatomy"]'::jsonb,1,'Supply and prices are core topics in microeconomics.','original'),
('113.61.c.1.B',3,'For a project on inflation, Rosa reads a Federal Reserve report, an economics journal article and a business news story. Why use varied sources?','["To avoid citing anyone", "To lengthen the paper", "To compare data and viewpoints and check claims against each other", "To find only one number"]'::jsonb,2,'Literature review uses varied sources.','original'),
('113.61.c.1.B',3,'Which source is the strongest choice for data on national unemployment rates?','["An unsigned forum post", "A product advertisement", "A friend''s guess", "A Bureau of Labor Statistics release"]'::jsonb,3,'Government statistical agencies publish reliable data.','original'),
('113.61.c.1.C',3,'A student sees that three local grocery stores closed in two years, leaving neighbors with little access to fresh food. This helps her do what?','["Identify an economic problem to study", "Grade the project", "Print the poster", "Write a bibliography"]'::jsonb,0,'Projects begin with a real problem.','original'),
('113.61.c.1.C',3,'Which is a clear problem statement for an economics project?','["Rent is a word", "Rising rents in our town are pushing out workers who earn the median wage", "Money exists", "I like economics"]'::jsonb,1,'Specific statements name the issue and the group affected.','original'),
('113.61.c.1.D',3,'Why would a student interview a small-business owner before finalizing a project on startup costs?','["To avoid a proposal", "To copy the owner''s books", "To learn whether the project is realistic from a professional''s view", "To skip research"]'::jsonb,2,'Professional input tests appropriateness.','original'),
('113.61.c.1.D',3,'A student surveys 50 shoppers about how price changes affect what they buy. This survey is what kind of evidence?','["A citation", "A final report", "A secondary source", "Primary data"]'::jsonb,3,'Surveys produce primary data.','original'),
('113.61.c.1.E',3,'Which pieces belong in an economics project proposal?','["Questions, goals and objectives, rationale and procedures", "A list of snacks", "The final grade", "Only a title"]'::jsonb,0,'Proposals state what, why and how.','original'),
('113.61.c.1.E',3,'A proposal says, "I will compare gas prices at six stations each Monday for five weeks." Which part of the proposal is this?','["Bibliography", "Procedure", "Rationale", "Conclusion"]'::jsonb,1,'A procedure lists the steps for gathering data.','original'),
('113.61.c.2.A',3,'Shadowing a bank loan officer for a morning helps a student do what?','["Skip the proposal", "Earn a license", "Understand the profession''s requirements and practices through observation", "Avoid research"]'::jsonb,2,'Observation builds career understanding.','original'),
('113.61.c.2.A',3,'While observing an accountant, a student notes the certification the job requires. Why record it?','["It ends the project", "It sets the grade", "It replaces interviews", "It shows the requirements of the profession"]'::jsonb,3,'Requirements are part of career knowledge.','original'),
('113.61.c.2.B',3,'A student builds a simple supply and demand model in a spreadsheet the way an economist would. This is what?','["Simulating the methods and technologies of the field", "Avoiding technology", "Copying another paper", "Memorizing a glossary"]'::jsonb,0,'Simulation lets students practice professional methods.','original'),
('113.61.c.2.B',3,'Which activity best simulates economic research methods?','["Reading only headlines", "Analyzing a data set with graphs and averages", "Guessing a trend", "Skipping the data"]'::jsonb,1,'Economists analyze data.','original'),
('113.61.c.2.C',3,'Preliminary research shows the data a student planned to use is no longer published. What should the student do?','["Invent numbers", "Ignore the problem", "Revise the proposal to use an available data source", "Drop the project"]'::jsonb,2,'Proposals are revised after preliminary research.','original'),
('113.61.c.2.C',3,'Why revise an original proposal after early research?','["To hide goals", "To avoid the audience", "To remove all questions", "To reflect changes needed based on what the research shows"]'::jsonb,3,'Revision keeps the plan realistic.','original'),
('113.61.c.3.A',3,'A student wants to produce a budget guide for teens. Who should help define the product?','["A financial counselor or other appropriate professional", "A classmate who has not studied money", "No one", "A stranger online"]'::jsonb,0,'Professional collaboration sharpens the product.','original'),
('113.61.c.3.B',3,'A plan for completing a report with eight weeks left should list what?','["No dates", "Tasks, deadlines and the resources needed", "Favorite songs", "Only the topic"]'::jsonb,1,'Plans organize time and resources.','original'),
('113.61.c.3.B',3,'A student divides a 10-week project into data, analysis, writing and review phases. This is what?','["A final reflection", "Plagiarism", "Developing a plan for completion", "Peer review only"]'::jsonb,2,'Phases support planning.','original'),
('113.61.c.3.C',3,'Which is a measurable success criterion for a pricing study?','["Do something useful", "Make it good", "Try hard", "Prices collected from at least 10 stores over 4 weeks"]'::jsonb,3,'Measurable criteria can be checked.','original'),
('113.61.c.3.D',3,'A product for first-time investors should use what kind of language?','["Clear, plain language with defined terms", "Random slang", "No explanations", "Dense jargon"]'::jsonb,0,'Appropriateness for the audience matters.','original'),
('113.61.c.3.D',3,'Before presenting to a chamber of commerce, why consider the audience?','["To ignore them", "To match the content and tone to what the members need", "To avoid evidence", "To skip research"]'::jsonb,1,'Audience shapes the product.','original'),
('113.61.c.3.E',3,'After finishing the plan, a student begins collecting data and drafting charts. This step is called what?','["Choosing a career", "Defining the problem", "Implementing the plan", "Grading"]'::jsonb,2,'Implementation carries out the plan.','original'),
('113.61.c.3.E',3,'A student''s data source is delayed by two weeks. The best step is to do what?','["Copy another study", "Hide the delay", "Abandon the project", "Adjust the schedule and keep the goals"]'::jsonb,3,'Plans can be adjusted.','original'),
('113.61.c.3.F',3,'A project journal should include what?','["Dated notes on each phase and reflections on learning", "Only the final grade", "Unrelated drawings", "Blank pages"]'::jsonb,0,'The journal documents the process.','original'),
('113.61.c.3.F',3,'Why write reflections in a journal during a project?','["To replace the product", "To track decisions and learning across phases", "To avoid data", "To skip the plan"]'::jsonb,1,'Reflection builds learning.','original'),
('113.61.c.4.A',3,'After a practice run, a student trims her presentation from 18 minutes to 10 to fit the limit. This is what?','["Ignoring feedback", "Plagiarizing", "Reviewing and revising the plan to present findings", "Changing the topic"]'::jsonb,2,'Revision improves presentations.','original'),
('113.61.c.4.A',3,'Which revision best improves a presentation about price trends?','["Removing all data", "Reading every number aloud", "Adding unrelated jokes", "Adding a line graph that shows the trend clearly"]'::jsonb,3,'Visuals clarify findings.','original'),
('113.61.c.4.B',3,'To present to a community lending board, a student must first do what?','["Arrange the date, room and equipment with the audience", "Skip the audience", "Delete the slides", "Delay the project"]'::jsonb,0,'Logistics make a presentation possible.','original'),
('113.61.c.4.B',3,'A student confirms the room, the time and the laptop connection. This is what?','["Writing a proposal", "Making arrangements for the presentation", "Citing sources", "Collecting data"]'::jsonb,1,'Preparation avoids problems.','original'),
('113.61.c.4.C',3,'Presenting like a professional economist includes what?','["Mumbling", "Reading with your back turned", "Explaining methods, results and limits with evidence", "Avoiding evidence"]'::jsonb,2,'Professionals present methods and results.','original'),
('113.61.c.4.C',3,'Which behavior best simulates a professional analyst''s presentation?','["Hiding sources", "Telling only a story", "Skipping the findings", "Stating a clear finding and supporting it with data"]'::jsonb,3,'Evidence supports claims.','original'),
('113.61.c.4.D',3,'An audience member suggests a clearer axis label on a chart. The best response is to do what?','["Consider the feedback and decide how to improve the chart", "Argue", "Ignore it", "Delete the chart"]'::jsonb,0,'Feedback helps refine work.','original'),
('113.61.c.4.D',3,'Why consider feedback from professionals who watch a presentation?','["It replaces the product", "It shows strengths and areas to improve", "It is always wrong", "It ends the project"]'::jsonb,1,'Professional feedback improves work.','original'),
('113.61.c.4.E',3,'A student asks whether her findings on local wages could help a city plan job programs. This is what?','["Writing citations", "Defining the problem", "Reflecting on the study''s potential impact on the field", "Collecting data"]'::jsonb,2,'Impact reflection looks beyond the project.','original'),
('113.61.c.4.E',3,'Which question best explores a study''s potential impact on economics?','["Who sat in front?", "What font did I use?", "How long was the break?", "How could these findings change how businesses or policymakers act?"]'::jsonb,3,'Impact looks at influence on the field.','original'),
('113.61.c.4.F',3,'At the end of a project, a student writes what she learned about her own work habits. This is what?','["Reflecting on personal learning experiences", "Defining a problem", "Making a plan", "Collecting data"]'::jsonb,0,'Personal reflection closes the study.','original'),
('113.61.c.4.F',3,'Which question best guides a personal reflection after a research project?','["How long was lunch?", "What did I learn about the research process and about myself?", "What color was the title?", "Who was late?"]'::jsonb,1,'Reflection examines learning.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
